// Reads the resolved DTCG permutations under design/tokens/ (generated by `pnpm generate`).
import { config } from './repo';

type Json = Record<string, any>;

const files = import.meta.glob<Json>('../../../../design/tokens/*.tokens.json', { eager: true, import: 'default' });
// The core's documents, and those of the components that live in a layer (tokens/systems/<layer>/comp/).
const sources = import.meta.glob<Json>(['../../../../tokens/{sys,comp,ref}/*.tokens.json', '../../../../tokens/systems/*/comp/*.tokens.json'], { eager: true, import: 'default' });
// Each preset's resolved permutations (design/tokens/<id>/), for a component that lives in its layer.
const presetFiles = import.meta.glob<Json>('../../../../design/tokens/*/*.tokens.json', { eager: true, import: 'default' });

/** Context id → resolved token tree. Ids look like `light`, `dark`, `light-high`. */
export const contexts: Record<string, Json> = Object.fromEntries(
  Object.entries(files).map(([file, tree]) => [file.split('/').pop()!.replace(`${config.namespace}.`, '').replace('.tokens.json', ''), tree]),
);
export const contextIds = Object.keys(contexts).sort();

export interface Token {
  path: string[];
  name: string; // dotted
  cssVar: string;
  type: string;
  value: any;
  description?: string;
}

export const cssVar = (path: string[]) => `${config.web.cssPrefix}-${path.slice(1).join('-')}`;

function walk(node: Json, path: string[], inheritedType: string | undefined, out: Token[]) {
  const type = node.$type ?? inheritedType;
  if ('$value' in node) {
    out.push({ path, name: path.join('.'), cssVar: cssVar(path), type, value: node.$value, description: node.$description });
    return;
  }
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith('$') || child === null || typeof child !== 'object') continue;
    walk(child, [...path, key], type, out);
  }
}

function at(tree: Json, dotted: string): Json | undefined {
  return dotted.split('.').reduce<Json | undefined>((node, key) => node?.[key], tree);
}

/**
 * All tokens under a dotted group (e.g. `tanrei.sys.color`) in one context — of the default system, or of `system`: a
 * component that lives in a layer has its tokens only in the systems that descend from it, and is read in that layer's.
 */
export function tokensIn(group: string, context = 'light', system?: string): Token[] {
  const preset = system && system !== ns && system !== 'core' ? Object.entries(presetFiles).find(([file]) => file.endsWith(`/${system}/${ns}.${context}.tokens.json`))?.[1] : undefined;
  if (system && system !== ns && system !== 'core' && !preset) throw new Error(`design/tokens/${system}/ has no "${context}" context. Run pnpm generate.`);
  const tree = preset ?? contexts[context];
  if (!tree) throw new Error(`design/tokens/ has no "${context}" context. Run pnpm generate.`);
  const node = at(tree, group);
  const out: Token[] = [];
  if (node) walk(node, group.split('.'), undefined, out);
  return out;
}

/** Group-level and token-level `$description`s from the hand-written token sources. */
export function sourceDescription(dotted: string): string | undefined {
  for (const tree of Object.values(sources)) {
    const node = at(tree, dotted);
    if (node?.$description) return node.$description;
  }
  return undefined;
}

/** The alias a source token points at (`{tanrei.sys.shape.corner.small}` → `tanrei.sys.shape.corner.small`). */
export function sourceAlias(dotted: string): string | undefined {
  for (const tree of Object.values(sources)) {
    const value = at(tree, dotted)?.$value;
    if (typeof value === 'string' && value.startsWith('{')) return value.slice(1, -1);
  }
  return undefined;
}

/**
 * The sets of tokens a component reads beside its own group, and that are no component's: a document
 * of tokens/comp/ that names its readers (`dev.<namespace>.shared.readers`). Returned as dotted groups under the
 * namespace (`comp.input-box` for a text input, a select, a combobox, a number input and a color input).
 */
export function sharedSetsOf(component: string): string[] {
  const out: string[] = [];
  for (const tree of Object.values(sources)) {
    for (const [name, group] of Object.entries<Json>(tree[config.namespace]?.comp ?? {})) {
      if (group?.$extensions?.[`dev.${config.namespace}.shared`]?.readers?.includes(component)) out.push(`comp.${name}`);
    }
  }
  return out.sort();
}

export const ns = config.namespace;

// ── Shipped design systems ──────────────────────────────────────────────
// Layers in tokens/systems/ and each system's resolved light context under design/tokens/<id>/ (the default system's
// files sit at the top of design/tokens/).
const layerFiles = import.meta.glob<Json>('../../../../tokens/systems/*.system.json', { eager: true, import: 'default' });
const systemFiles = import.meta.glob<Json>('../../../../design/tokens/*/*.light.tokens.json', { eager: true, import: 'default' });

export interface ShippedSystem {
  id: string;
  name: string;
  extends?: string;
  /** Resolved tokens, light scheme. */
  tree: Json;
}
/**
 * The default system first, then the presets by id. The root layer (the one without `extends`) is the first layer of
 * every chain and has no output of its own, so it is not one of them.
 */
export const shippedSystems: ShippedSystem[] = Object.values(layerFiles)
  .filter((layer) => layer.extends)
  .sort((a, b) => Number(a.id !== ns) - Number(b.id !== ns) || a.id.localeCompare(b.id))
  .map((layer) => {
    const tree = layer.id !== ns ? Object.entries(systemFiles).find(([file]) => file.split('/').at(-2) === layer.id)?.[1] : contexts.light;
    if (!tree) throw new Error(`design/tokens/ has no resolved tokens for the system "${layer.id}". Run pnpm generate.`);
    return { id: layer.id, name: layer.name, extends: layer.extends, tree };
  });

/** A token's node in the hand-written sources (with its `$extensions`), or undefined. */
export function sourceNode(dotted: string): Json | undefined {
  for (const tree of Object.values(sources)) {
    const node = at(tree, dotted);
    if (node) return node;
  }
  return undefined;
}

/** The names a choice of kind may take: `$extensions["dev.tanrei.enum"].values` of the source token. */
export const enumValues = (dotted: string): string[] | undefined => sourceNode(dotted)?.$extensions?.['dev.tanrei.enum']?.values;

/** What a shipped system resolves a token to, as text. A choice of kind is shown by name, never by its index. */
export function systemValue(system: ShippedSystem, dotted: string): string {
  const node = at(system.tree, dotted);
  if (!node || !('$value' in node)) return '—';
  const names = enumValues(dotted);
  if (names) return names[node.$value] ?? String(node.$value);
  const type = node.$type ?? sourceNode(dotted)?.$type ?? sourceNode(dotted.split('.').slice(0, -1).join('.'))?.$type;
  return formatValue({ path: dotted.split('.'), name: dotted, cssVar: cssVar(dotted.split('.')), type, value: node.$value });
}

// ── Formatting ──────────────────────────────────────────────────────────
export function colorCss(value: any): string {
  if (!value || typeof value !== 'object') return String(value);
  const alpha = value.alpha ?? 1;
  if (alpha >= 1 && value.hex) return value.hex;
  const [r, g, b] = value.components.map((c: number) => Math.round(c * 255));
  return `rgb(${r} ${g} ${b} / ${alpha})`;
}
export function colorLabel(value: any): string {
  const alpha = value?.alpha ?? 1;
  return alpha >= 1 ? value.hex : `${value.hex} · ${Math.round(alpha * 1000) / 10}%`;
}
export const dimension = (value: any) => (value && typeof value === 'object' ? `${value.value}${value.unit}` : String(value));
export const bezier = (value: number[]) => `cubic-bezier(${value.join(', ')})`;
export function shadowCss(layers: any[]): string {
  return layers
    .map((l) => `${l.inset ? 'inset ' : ''}${dimension(l.offsetX)} ${dimension(l.offsetY)} ${dimension(l.blur)} ${dimension(l.spread)} ${colorCss(l.color)}`)
    .join(', ');
}
export function formatValue(token: Token): string {
  switch (token.type) {
    case 'color':
      return colorLabel(token.value);
    case 'dimension':
    case 'duration':
      return dimension(token.value);
    case 'cubicBezier':
      return bezier(token.value);
    case 'shadow':
      return shadowCss(token.value);
    case 'fontFamily':
      return Array.isArray(token.value) ? token.value.join(', ') : String(token.value);
    case 'typography':
      return `${token.value.fontWeight} ${dimension(token.value.fontSize)}/${token.value.lineHeight}`;
    default:
      return typeof token.value === 'object' ? JSON.stringify(token.value) : String(token.value);
  }
}
